parameters.inputSchema:
{
	"type": "object",
	"properties": {
		"type": {
			"type": "string",
			"description": "The specific post type for today's LinkedIn content (e.g., 'Belief Reversal', 'Translation', 'Rejection Story', '1-Minute Fix', 'Storytelling', etc.)."
		},
		"goal": {
			"type": "string",
			"description": "The primary objective of this post type—such as reach, saves, comments, watch time, or follower growth. Describes what outcome this style is intended to achieve."
		},
		"description": {
			"type": "string",
			"description": "A short explanation of how this post type works, what structure it follows, and why it is effective for today's content strategy."
		}
	},
	"required": ["type", "goal", "description"]
}

{
  "type": "object",
  "properties": {
    "hook_type": {
      "type": "string",
      "description": "The category of hook chosen based on the post type and goal. Examples include: 'Negative Warning', 'Lie Reveal', 'Curiosity Gap', 'Educational', 'Storytelling', 'Specific Audience Call-Out'."
    },
    "sample_hook": {
      "type": "string",
      "description": "A concrete example of a hook phrase that fits the selected hook_type. This is a ready-to-use hook or a strong starting point for the final LinkedIn post."
    }
  },
  "required": ["hook_type", "sample_hook"]
}

{
  "type": "object",
  "properties": {
    "draft": {
      "type": "string",
      "description": "The fully written LinkedIn post generated by the AI, including the hook, story structure, BUT → THEREFORE loops, sentence-length variation, personal lens, and hashtags. This is the final post text ready to be sent for Slack approval."
    }
  },
  "required": ["draft"]
}

parameters.blocksUi:
={
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "🚀 New LinkedIn Draft Generated",
        "emoji": true
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Post Type:*\n{{ $('Get Post Type from Docs').item.json.output.type || 'Standard Post' }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Hook Type:*\n{{ $('Choose Best Hook').item.json.output.hook_type || 'General Hook' }}"
        }
      ]
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Sample Hook:*\n{{ JSON.stringify(($('Choose Best Hook').item.json.output.sample_hook || 'No hook generated').substring(0, 2800)).slice(1, -1) }}"
      }
    },
    {
      "type": "divider"
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Draft:*\n{{ JSON.stringify(($('Generate Post').item.json.output.draft || 'No draft content generated').substring(0, 2800)).slice(1, -1) }}"
      }
    },
    {
      "type": "divider"
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "*Image URL:* {{ $json.webViewLink || 'No Image Available' }}"
        }
      ]
    },
    {
      "type": "divider"
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "💬 *Approval Instructions:* Reply to this message thread with:\n• `APPROVE`\n• `REJECT: <your feedback>`"
        }
      ]
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "_Waiting for your response…_"
        }
      ]
    },
    {
      "type": "divider"
    }
  ]
}
